// 1. Limitations: Un-overloadable Operators
// Operator behavior cannot be changed for built-in types.

class MyInt {};
// Valid: Must involve at least one UDT (User-Defined Type)
MyInt operator+(const MyInt& a, const MyInt& b);

// Invalid: Cannot redefine behavior for fundamental types
// int operator*(int a, int b); // ERROR

// Forbidden Operators (Cannot be Overloaded):
// :: (Scope resolution)
// . (Member selector)
// .* (Member pointer selector)
// ?: (Ternary conditional)
// sizeof, typeid, static_cast, etc.


// 2. Unary Overloads: Prefix vs. Postfix

class Counter {
public:
    // Prefix increment (++obj)
    Counter& operator++();

    // Postfix increment (obj++): Requires dummy 'int' parameter
    Counter operator++(int);
};


// 3. Special Overloads: Required Member Functions

class List {
    int* data;
public:
    // Must be a non-static member function: Assignment (=)
    List& operator=(const List& other);

    // Must be a non-static member function: Subscript ([])
    int& operator[](size_t index);

    // Must be a non-static member function: Function Call (())
    int operator()(int multiplier) const;

    // Must be a non-static member function: Arrow (->)
    List* operator->();
};
